style.css:
@-moz-document domain("mods.vintagestory.at") {
:root {
    --bg: #15171b;
    --surface: #1d2025;
    --surface-2: #262a31;
    --border: #353a43;
    --text: #d4d7dc;
    --muted: #8f96a1;
    --heading: #eceff3;
    --accent: #c8a35f;
    --link: #7db0e3;
    --link-hover: #a8cdf0;
    --link-visited: #b39ad4;
    color-scheme: dark;
  }

  html, body {
    background: var(--bg) !important;
    color: var(--text) !important;
  }

  /* Remove light backgrounds from layout and text elements */
  div, section, article, aside, header, footer, nav, main, form, fieldset,
  ul, ol, li, dl, dt, dd, table, thead, tbody, tfoot, tr, td, th, caption,
  details, summary, p, span, label {
    background-color: transparent !important;
    color: var(--text) !important;
  }

  a *, a span { color: inherit !important; }

  /* Header and footer surfaces */
  header, nav {
    background-color: var(--surface) !important;
    border-bottom: 1px solid var(--border) !important;
  }
  footer {
    background-color: var(--surface) !important;
    border-top: 1px solid var(--border) !important;
  }
  footer, footer * { color: var(--muted) !important; }

  /* Links */
  a { color: var(--link) !important; }
  a:visited { color: var(--link-visited) !important; }
  a:hover, a:focus { color: var(--link-hover) !important; }

  /* Headings */
  h1, h2, h3, h4, h5, h6 { color: var(--heading) !important; }
  h1, h2 { color: var(--accent) !important; }

  /* Borders */
  * { border-color: var(--border) !important; }
  hr { background-color: var(--border) !important; border-color: var(--border) !important; }

  /* Tables */
  table { border-collapse: collapse; }
  th {
    background-color: var(--surface-2) !important;
    color: var(--heading) !important;
  }
  tbody tr:nth-child(even) td { background-color: rgba(255,255,255,.03) !important; }
  tbody tr:hover td { background-color: rgba(255,255,255,.06) !important; }

  /* Form fields */
  input:not([type=checkbox]):not([type=radio]):not([type=submit]):not([type=button]),
  textarea, select {
    background-color: var(--surface-2) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
  }
  input:focus, textarea:focus, select:focus {
    outline: 1px solid var(--accent) !important;
    border-color: var(--accent) !important;
  }
  ::placeholder { color: var(--muted) !important; opacity: 1; }

  /* Buttons */
  button, input[type=submit], input[type=button], .button, .btn, a.button {
    background-color: var(--surface-2) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
  }
  button:hover, input[type=submit]:hover, input[type=button]:hover,
  .button:hover, .btn:hover, a.button:hover {
    background-color: #313640 !important;
    border-color: var(--accent) !important;
  }

  /* Code and quotes */
  pre, code, kbd, samp {
    background-color: #0f1114 !important;
    color: #e0e3e8 !important;
  }
  blockquote {
    background-color: var(--surface) !important;
    border-left: 3px solid var(--accent) !important;
  }

  /* Inline styles inside mod descriptions and comments */
  [style*="color: #000"], [style*="color:#000"],
  [style*="color: black"], [style*="color:black"],
  [style*="rgb(0, 0, 0)"],
  font[color="#000000"], font[color="black"] {
    color: var(--text) !important;
  }
  [style*="background-color: #fff"], [style*="background-color:#fff"],
  [style*="background: #fff"], [style*="background:#fff"],
  [style*="background-color: white"], [style*="background-color: rgb(255, 255, 255)"] {
    background-color: transparent !important;
  }

  ::selection { background: var(--accent); color: #15171b; }

  /* Optional: uncomment if the download/comment icons are dark and hard to see
  img[src*="/web/img/download.png"],
  img[src*="/web/img/comments.png"] { filter: invert(.8); }
  */

  /* Add leftover fixes here after inspecting the element in devtools */
}
